import{_ as a,o as i,c as e,a2 as t}from"./chunks/framework.Dp0m3YJZ.js";const S=JSON.parse('{"title":"Spec 04：WUWAOS 開機 ASCII 展開動畫","description":"","frontmatter":{},"headers":[],"relativePath":"SPEC-04-boot-splash.md","filePath":"SPEC-04-boot-splash.md","lastUpdated":1792834243000}'),s={name:"SPEC-04-boot-splash.md"};function o(r,l,h,p,n,c){return i(),e("div",null,[...l[0]||(l[0]=[t('<h1 id="spec-04-wuwaos-開機-ascii-展開動畫" tabindex="-1">Spec 04：WUWAOS 開機 ASCII 展開動畫 <a class="header-anchor" href="#spec-04-wuwaos-開機-ascii-展開動畫" aria-label="Permalink to &quot;Spec 04：WUWAOS 開機 ASCII 展開動畫&quot;">​</a></h1><h2 id="目標與範圍" tabindex="-1">目標與範圍 <a class="header-anchor" href="#目標與範圍" aria-label="Permalink to &quot;目標與範圍&quot;">​</a></h2><p>使用者希望開機以 ASCII ART（文字字元圖案）顯示 WUWAOS，從中央逐漸向兩側展開。 在既有 QEMU virt 核心加入啟動畫面，結束後保留完整字樣並照常進入 shell（命令列介面）。 不變更行程管理、pipe（資料管道）或系統呼叫，不新增測試程式碼，不自行 commit / push。 前一版規格保留於 SPEC-03-shell-pipe.md，早期里程碑保留於 SPEC-01／02。</p><h2 id="設計與演算法" tabindex="-1">設計與演算法 <a class="header-anchor" href="#設計與演算法" aria-label="Permalink to &quot;設計與演算法&quot;">​</a></h2><ul><li>新增 kernel/splash.c/h，只負責啟動畫面，由 main.c 在例外入口安裝後、核心初始化訊息前呼叫。</li><li>以 # 與空格組成 7 行、52 欄的 WUWAOS，左右留白，適合至少 80 欄的 ANSI 終端。</li><li>動畫以中心為軸，每次多揭露左右各一欄，外側尚未揭露的字元以空白遮罩；26 個畫面逐步顯示完整字樣。</li><li>ANSI escape sequence（終端控制碼）清除舊啟動畫面、回到畫面起點重繪、暫時隱藏游標；最後還原游標。不逐行捲動堆疊動畫。</li><li>使用 rdtime（讀取硬體時間計數器指令）控制每格約 45 ms，最後停留約 200 ms；不是依主機 CPU 速度估算的空迴圈。</li><li>QEMU virt 時基固定按目前平台的 10 MHz 設定；不新增 timer interrupt（計時器中斷）或延遲系統呼叫。僅開機短時間輪詢等待。</li><li>圖案逐欄遮罩，單格 O(H×W)，H=7、W=52，總空間固定；中心展開是揭露圖案，不是縮放字型。</li><li>畫面清除會移走先前 OpenSBI 的可見文字；核心啟動資訊在動畫後重新從下方輸出。</li></ul><h2 id="修改檔案與步驟" tabindex="-1">修改檔案與步驟 <a class="header-anchor" href="#修改檔案與步驟" aria-label="Permalink to &quot;修改檔案與步驟&quot;">​</a></h2><ol><li>新增 splash.c/h、調整 main.c 與 Makefile 的核心來源清單。</li><li>更新 README 與 CODE_GUIDE 的啟動行為、檔案功能與平台限制。</li><li>建置並在實際 QEMU 終端確認中心到完整圖案的連續畫面、游標還原、shell 可輸入。</li><li>將實際驗收填入本文件，保留之前尚未提交的改動。</li></ol><h2 id="驗收條件" tabindex="-1">驗收條件 <a class="header-anchor" href="#驗收條件" aria-label="Permalink to &quot;驗收條件&quot;">​</a></h2><ul><li>原始碼可建置，沒有未解析符號。</li><li>啟動時由窄中央區域逐步揭露至完整 WUWAOS，畫面位置固定且不因換行捲動。</li><li>結束後保留圖案並恢復游標，wuwaos&gt; 可執行 ps 等正常指令。</li><li>未新增測試程式碼；非 ANSI 或小於 80 欄終端不在本次驗收範圍。</li></ul><h2 id="實際驗收紀錄" tabindex="-1">實際驗收紀錄 <a class="header-anchor" href="#實際驗收紀錄" aria-label="Permalink to &quot;實際驗收紀錄&quot;">​</a></h2><p>2026-10-16：</p><ul><li>Clang 建置成功，沒有新增測試程式碼。</li><li>實際 QEMU ANSI 終端呈現中央狹窄區域到完整 WUWAOS 的逐格展開，最後保留完整字樣與平台副標題。</li><li>UART 原始輸出紀錄確認 26 次定點重繪，動畫區域沒有 NUL 字元，結束時有游標還原控制碼。</li><li>每行圖案均為 52 個字元，實際畫面沒有超過 80 欄或逐格捲動。</li><li>動畫後進入 wuwaos&gt;，實際輸入 ps 得到 shell PCB 列表，exit 正常結束，再離開 QEMU。</li><li>平台資訊顯示時間基準 10000000 Hz，符合延遲計算。預定等待時間 26×45+200=1370 ms，未進行獨立牆鐘精密計時。</li><li>本機 build/splash-console.log 保存原始序列輸出，不納入 Git。</li></ul><p>非 ANSI、小於 80 欄、其他時基硬體尚未驗證；不宣稱跨平台支援。此次不變更既有 process／pipe 行為。</p>',13)])])}const u=a(s,[["render",o]]);export{S as __pageData,u as default};
